#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, x, y;
    cin >> n >> x >> y;

    vector<ll> dp(n + 1);
    if (n >= 1) dp[1] = x;

    for (ll i = 2; i <= n; ++i) {
        dp[i] = dp[i - 1] + x;
        dp[i] = min(dp[i], dp[(i + 1) / 2] + y + (i & 1) * x);
    }

    cout << dp[n];
    return 0;
}

